def main():
    path = r"app\src\main\java\com\aman\gigi\ui\GalaxyView.kt"
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()

    # Find where Canvas draw operations end
    start_str = "        // Build draw order (sun + planets) by depth"
    end_str = "        // Recenter button"

    start_idx = content.find(start_str)
    end_idx = content.find(end_str)

    if start_idx == -1 or end_idx == -1:
        print("Could not find blocks")
        return

    correct_block = """        // Build draw order (sun + planets) by depth
        data class Item(val planet: GPlanet?, val depth: Float)
        val items = ArrayList<Item>(planets.size + 1)
        planets.forEach { p ->
            val ea = p.angle + rotY
            items.add(Item(p, kotlin.math.sin(ea)))
        }
        items.add(Item(null, 0f)) // sun
        items.sortBy { it.depth }

        val pr = minDim * 0.052f * zoom
        items.forEach { it ->
            val p = it.planet
            if (p == null) drawSun(pcx, pcy, minDim, zoom, sunBmp, centerLabel, frame)
            else drawPlanet(p, pcx, pcy, minDim, zoom, tilt, rotY, pr, moonBmp) { mi ->
                if (!p.isGroup) false
                else !groupMemberEmojis[p.id]?.getOrNull(mi).isNullOrBlank()
            }
        }
    } // End of Canvas

    // 💫 EMOJI LAYER: animated 3D fluent emojis (sun + planets + moons), depth ordered 💫
    fun emojiFor(key: String, fallback: String): String =
        prefs.getString("emoji_$key", null)
            ?.takeIf { it.startsWith("file:///") || it.startsWith("http") }
            ?: fallback

    androidx.compose.foundation.layout.BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        val density = androidx.compose.ui.platform.LocalDensity.current
        val w = constraints.maxWidth.toFloat()
        val h = constraints.maxHeight.toFloat()
        val cx = w / 2f
        val cy = h / 2f
        val pcx = cx + panX
        val pcy = cy + panY
        val minDim = kotlin.math.min(w, h)
        val pr = minDim * 0.052f * zoom

        val composeItems = ArrayList<Pair<GPlanet?, Float>>(planets.size + 1)
        planets.forEach { p ->
            val ea = p.angle + rotY
            composeItems.add(Pair(p, kotlin.math.sin(ea)))
        }
        composeItems.add(Pair(null, 0f))
        composeItems.sortBy { it.second }

        composeItems.forEach { it ->
            val p = it.first
            if (p == null) {
                val r = pr * 1.5f * 1.0f // sun scale
                val url = emojiFor("self", "file:///android_asset/galaxy/emoji/sun_with_face.png")
                androidx.compose.foundation.layout.Box(modifier = Modifier
                    .androidx.compose.foundation.layout.offset { androidx.compose.ui.unit.IntOffset((pcx - r).toInt(), (pcy - r).toInt()) }
                    .androidx.compose.foundation.layout.size(with(density) { (r * 2).toDp() })
                ) {
                    coil.compose.AsyncImage(
                        model = coil.request.ImageRequest.Builder(context).data(url).build(),
                        imageLoader = emojiLoader,
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize()
                    )
                }
            } else {
                val ea = p.angle + rotY
                val R = minDim * (0.17f + p.orbit * 0.115f) * zoom
                val x = pcx + R * kotlin.math.cos(ea)
                val y = pcy + R * tilt * kotlin.math.sin(ea)
                val scl = 0.66f + 0.42f * ((kotlin.math.sin(ea) + 1f) / 2f)
                val r = pr * p.sizeMul * scl

                val url = emojiFor(p.id, "file:///android_asset/galaxy/emoji/full_moon_face.png")
                androidx.compose.foundation.layout.Box(modifier = Modifier
                    .androidx.compose.foundation.layout.offset { androidx.compose.ui.unit.IntOffset((x - r).toInt(), (y - r).toInt()) }
                    .androidx.compose.foundation.layout.size(with(density) { (r * 2).toDp() })
                ) {
                    coil.compose.AsyncImage(
                        model = coil.request.ImageRequest.Builder(context).data(url).build(),
                        imageLoader = emojiLoader,
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize()
                    )
                }

                if (p.isGroup) {
                    p.moons.forEachIndexed { mi, m ->
                        val moonUrl = groupMemberEmojis[p.id]?.getOrNull(mi)
                        if (!moonUrl.isNullOrBlank()) {
                            val mx = x + r * m.radius * kotlin.math.cos(m.angle)
                            val my = y + r * m.radius * tilt * kotlin.math.sin(m.angle)
                            val mr = r * 0.32f
                            androidx.compose.foundation.layout.Box(modifier = Modifier
                                .androidx.compose.foundation.layout.offset { androidx.compose.ui.unit.IntOffset((mx - mr).toInt(), (my - mr).toInt()) }
                                .androidx.compose.foundation.layout.size(with(density) { (mr * 2).toDp() })
                            ) {
                                coil.compose.AsyncImage(
                                    model = coil.request.ImageRequest.Builder(context).data(moonUrl).build(),
                                    imageLoader = emojiLoader,
                                    contentDescription = null,
                                    modifier = Modifier.fillMaxSize()
                                )
                            }
                        }
                    }
                }
            }
        }
    }

"""

    content = content[:start_idx] + correct_block + content[end_idx:]

    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print("GalaxyView.kt fixed!")

if __name__ == "__main__":
    main()
'

